-- SIGMA RADAR Fit / estrutura inicial Supabase
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text,sex text,age int,height_cm numeric,initial_weight_kg numeric,target_weight_kg numeric,goal_text text,training_days text[],minutes_per_session int,experience text,medications_text text,supplements_text text,meals_per_day text,current_water_l numeric,sleep_hours numeric,created_at timestamptz default now());
create table if not exists public.daily_logs(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade,log_date date not null,training_completion numeric,nutrition_completion numeric,hydration_completion numeric,water_l numeric,score numeric,created_at timestamptz default now(),unique(user_id,log_date));
create table if not exists public.weekly_reviews(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade,week_start date not null,score numeric,summary text,keep_text text,increase_text text,reduce_text text,proposed_changes jsonb,user_approved boolean,created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.daily_logs enable row level security;alter table public.weekly_reviews enable row level security;
create policy profiles_own on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy daily_own on public.daily_logs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy weekly_own on public.weekly_reviews for all using(auth.uid()=user_id) with check(auth.uid()=user_id);